package com.example.domain.model.i18n

internal object DuaNl1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Bij het ontwaken", "Alle lof zij Allah die ons weer tot leven heeft gebracht nadat Hij ons deed sterven (slapen), en tot Hem is de terugkeer.", "Wordt gereciteerd direct na het ontwaken, als dank aan Allah.", "De Profeet ﷺ zei dit bij het ontwaken — de dag beginnen met dankbaarheid en het gedenken van het hiernamaals."),
        "dua_leaving_home" to DuaText("Bij het verlaten van huis", "In de naam van Allah, ik vertrouw op Allah, er is geen kracht of macht behalve bij Allah.", "Wordt gereciteerd bij het verlaten van huis voor bescherming.", "Tegen degene die dit zegt wordt gezegd: je bent geleid, voorzien en beschermd — en de satan houdt zich verre van hem."),
        "dua_anxiety_distress" to DuaText("Smeekbede tegen zorgen en verdriet", "O Allah, ik zoek toevlucht bij U tegen zorgen en verdriet, tegen zwakte en luiheid, tegen gierigheid en lafheid, tegen de last van schulden en overheersing door mensen.", "Bij zorgen, verdriet, schulden en innerlijke nood.", "De Profeet ﷺ zei dit vaak om toevlucht te zoeken tegen verdriet, luiheid en schulden."),
        "dua_sayyidul_istighfar" to DuaText("De meester van het berouw (Sayyidul Istighfar)", "O Allah, U bent mijn Heer, er is geen god dan U. U heeft mij geschapen en ik ben Uw dienaar. Ik houd mij zo goed mogelijk aan Uw verbond en belofte. Ik zoek toevlucht bij U tegen het kwaad dat ik heb gedaan. Ik erken Uw gunst aan mij en ik erken mijn zonde; vergeef mij, want niemand vergeeft zonden behalve U.", "Wordt 's ochtends en 's avonds gereciteerd — de beste smeekbede om vergeving die de Profeet ﷺ onderwees.", "Wie dit 's avonds met overtuiging zegt en die nacht sterft, gaat het Paradijs binnen; hetzelfde geldt voor wie het 's ochtends zegt."),
        "dua_parents" to DuaText("Smeekbede voor ouders", "Mijn Heer, wees hen genadig zoals zij mij als kind hebben opgevoed.", "Koranische smeekbede als dank voor de zorg van ouders in de jeugd.", "Allah heeft deze smeekbede voor ouders rechtstreeks in de Koran bevolen."),
        "dua_entering_mosque" to DuaText("Bij het betreden van de moskee", "O Allah, open voor mij de poorten van Uw genade.", "Wordt gereciteerd bij het betreden van de moskee met de rechtervoet.", "De Profeet ﷺ onderwees deze smeekbede voor het betreden van de moskee."),
        "dua_morning_asbahna" to DuaText("Ochtendgedenking", "Wij hebben de ochtend bereikt en met ons behoort de heerschappij aan Allah; alle lof zij Allah; er is geen god dan Allah alleen, zonder deelgenoot; aan Hem behoort de heerschappij en de lof, en Hij is Almachtig over alle dingen.", "Aanbevolen gedenking die 's ochtends wordt uitgesproken.", "De dag beginnen met de erkenning van Allahs heerschappij en eenheid."),
        "dua_evening_amsayna" to DuaText("Avondgedenking", "Wij hebben de avond bereikt en met ons behoort de heerschappij aan Allah; alle lof zij Allah; er is geen god dan Allah alleen, zonder deelgenoot; aan Hem behoort de heerschappij en de lof, en Hij is Almachtig over alle dingen.", "Aanbevolen gedenking die 's avonds wordt uitgesproken.", "De avond beginnen met de erkenning van Allahs heerschappij en eenheid."),
        "dua_before_sleep" to DuaText("Voor het slapengaan", "In Uw naam, o Allah, sterf ik en leef ik.", "Wordt gereciteerd nadat men is gaan liggen.", "De Profeet ﷺ zei dit voor het slapengaan."),
        "dua_travel" to DuaText("Reissmeekbede", "Glorie aan Hem die dit voor ons dienstbaar heeft gemaakt, terwijl wij dit zelf niet konden bedwingen; en voorwaar, tot onze Heer zullen wij terugkeren.", "Wordt gereciteerd bij het instappen na driemaal takbir.", "Aanbevolen reissmeekbede voor bescherming en zegen."),
        "dua_ayatul_kursi" to DuaText("Ayat al-Koersi na het gebed", "Allah, er is geen god dan Hij, de Levende, de Onderhouder van alles. Sluimer noch slaap overmant Hem. Aan Hem behoort wat in de hemelen en op de aarde is. Wie kan bemiddelen bij Hem zonder Zijn toestemming? Hij weet wat voor hen is en wat achter hen is. Zij omvatten niets van Zijn kennis, behalve wat Hij wil. Zijn troon strekt zich uit over de hemelen en de aarde, en het valt Hem niet zwaar deze te bewaken. Hij is de Verhevene, de Grootse.", "Wordt na elk verplicht gebed en voor het slapengaan gereciteerd.", "Wie dit na elk verplicht gebed reciteert, wordt alleen door de dood verhinderd het Paradijs binnen te gaan; wie het voor het slapen reciteert, blijft beschermd tot de ochtend."),
        "dua_hasbunallah" to DuaText("Allah is ons genoeg", "Allah is ons genoeg en Hij is de beste Beschermer.", "Wordt gereciteerd bij angst voor een vijand of groot gevaar.", "Abraham zei dit toen hij in het vuur werd geworpen, en de Profeet ﷺ zei het in tijden van gevaar."),
        "dua_entering_home" to DuaText("Bij het betreden van huis", "In de naam van Allah zijn wij binnengegaan, in de naam van Allah zijn wij uitgegaan, en op onze Heer Allah vertrouwen wij.", "Wordt gereciteerd bij het betreden van huis, met vermelding van Allahs naam en een groet.", "Tegen wie Allah gedenkt bij het betreden van huis en bij het eten, zegt de satan: er is geen onderdak of avondmaal voor jullie."),
        "dua_yunus" to DuaText("Smeekbede van profeet Jonas (vrede zij met hem)", "Er is geen god dan U, U bent verheven, voorwaar ik behoorde tot de onrechtvaardigen.", "Smeekbede van profeet Jonas in de buik van de vis — voor elke moeilijkheid.", "Geen moslim roept hiermee in enige zaak tot Allah, of Hij verhoort hem."),
        "dua_karb" to DuaText("Smeekbede bij grote nood", "Er is geen god dan Allah, de Verhevene, de Zachtmoedige. Er is geen god dan Allah, Heer van de geweldige Troon. Er is geen god dan Allah, Heer van de hemelen, de aarde en de nobele Troon.", "Wordt gereciteerd bij grote nood en benauwdheid.", "De Profeet ﷺ zei dit in tijden van nood."),
    )
}
